11	namespace amr_dispatcher_core::planning {
12	
13	// 业务站点锚点（来自 markers.yaml）：世界坐标 + 语义类型。
14	struct AnchorStation {
15	  std::string id;
16	  std::string type = "normal";  // "pickup", "dropoff", "charge", etc.
17	  double x = 0.0;
18	  double y = 0.0;
19	  double yaw = 0.0;
20	};
21	
22	struct TopologyBuilderConfig {
23	  // 站点距离最近路网边的最大吸附允许距离（米），超过则构建失败。
24	  double max_snap_dist_m = 2.0;
25	  std::string map_hash;
26	  std::string graph_version = "v1";
27	};
28	
29	struct TopologyBuildResult {
30	  bool success = false;
31	  std::string error_message;
32	  catalog::StationCatalog catalog;
33	};
34	
35	// 拓扑路网构建与站点吸附边拆分。
36	//
37	// 算法流水线：
38	//   1. 骨架特征点提取：识别 8 邻域环连通组数 != 2 的骨架像素
39	//      （端点=1、分叉点>=3、孤立点=0），每个特征点生成 RoadNode。
40	//      纯闭合环（无特征点）任取一环上像素作为 RoadNode，避免环丢失。
41	//   2. 骨架链追踪：从特征点沿骨架追踪到下一特征点，生成 CatalogStationEdge，
42	//      polyline 保存真实折线像素序列（世界坐标），distance_m 为累加长度。
43	//   3. 站点吸附：将每个 AnchorStation 正交投影到最近边的 polyline，
44	//      距离超过 max_snap_dist_m 时报错；投影点处将原边拆分为两条子边，
45	//      站点作为新节点接入路网。
46	//   4. 连通性校验：所有站点必须处于同一连通分量（通过 FindRoutePath 验证）。
47	//   5. 版本标记：写入 map_hash / graph_version，最后经 ValidateStationCatalog 校验。
48	TopologyBuildResult BuildTopologyCatalog(
49	    const BinaryGrid& skeleton, const MapGrid& map_info,
