257	TEST(TopologyGraphBuilderTest, PolylineAccumulatedLength_NotStraightLine) {
258	  // res = 1.0 m/px。骨架：(0,5) -> (4,5) 水平 4 像素 + (4,5) -> (4,8) 垂直
259	  // 3 像素，L 形折线总长度 = 4 + 3 = 7m，而起点终点直线距离 = 5m。
260	  const MapGrid map_info = MakeMapInfo(5, 9, 1.0);
261	  BinaryGrid skeleton = MakeSkeleton(5, 9);
262	  DrawHLine(skeleton, 5, 0, 4);
263	  DrawVLine(skeleton, 4, 5, 8);
264	
265	  // 站点放在两端附近（世界坐标：(0,5)->(0.5,5.5)，(4,8)->(4.5,8.5)）。
266	  std::vector<AnchorStation> anchors;
267	  anchors.push_back(MakeAnchor("s_a", 0.5, 5.5));
268	  anchors.push_back(MakeAnchor("s_b", 4.5, 8.5));
