270	  TopologyBuilderConfig config;
271	  config.max_snap_dist_m = 5.0;
272	  config.map_hash = "h5";
273	  config.graph_version = "v1";
274	
275	  const TopologyBuildResult result =
276	      BuildTopologyCatalog(skeleton, map_info, anchors, config);
277	
278	  ASSERT_TRUE(result.success) << result.error_message;
279	
280	  // 找 s_a -> s_b 路径，断言其累加距离接近 7m，而非 5m 直线距离。
281	  const auto path =
282	      catalog::FindRoutePath(result.catalog, "s_a", "s_b");
283	  ASSERT_TRUE(path.has_value());
284	
285	  // 路径距离由 catalog::EstimateRouteDistance 给出（经过中间拐角节点）。
286	  const auto dist =
287	      catalog::EstimateRouteDistance(result.catalog, "s_a", "s_b");
288	  ASSERT_TRUE(dist.has_value());
289	  // 累加长度应约等于 4 + 3 = 7m（容差 0.2m 吸收像素取整）。
290	  EXPECT_NEAR(*dist, 7.0, 0.2)
291	      << "折线累加长度应为 ~7m，实际 " << *dist << "m";
292	
293	  // 至少一条边上的累加距离大于其端点直线距离（验证 polyline 累积而非
294	  // 直线距离）。
295	  bool edge_with_accumulated = false;
296	  for (const auto& edge : result.catalog.edges) {
297	    if (edge.polyline.size() >= 3) {
298	      // 计算折线累加长度
299	      double accum = 0.0;
300	      for (size_t i = 1; i < edge.polyline.size(); ++i) {
301	        const auto& p0 = edge.polyline[i - 1];
302	        const auto& p1 = edge.polyline[i];
303	        accum += std::hypot(p1.first - p0.first, p1.second - p0.second);
304	      }
305	      // 直线距离
306	      const auto& p_first = edge.polyline.front();
307	      const auto& p_last = edge.polyline.back();
308	      const double straight = std::hypot(p_last.first - p_first.first,
309	                                         p_last.second - p_first.second);
310	      if (accum > straight + 0.5) {
311	        edge_with_accumulated = true;
312	        break;
313	      }
314	    }
315	  }
316	  EXPECT_TRUE(edge_with_accumulated)
317	      << "至少一条边的折线累加长度应大于端点直线距离";
318	}
