// Scratch edge-case probe for BuildTopologyCatalog (not committed).
#include "amr_dispatcher_core/planning/topology_graph_builder.hpp"

#include <cstdio>
#include <string>
#include <vector>

using namespace amr_dispatcher_core::planning;

namespace {

MapGrid MakeMapInfo(uint32_t w, uint32_t h, double res) {
  MapGrid g;
  g.width = w;
  g.height = h;
  g.resolution = res;
  g.data.assign(static_cast<size_t>(w) * h, kCellFree);
  return g;
}

BinaryGrid MakeSkeleton(uint32_t w, uint32_t h) {
  BinaryGrid g;
  g.width = w;
  g.height = h;
  g.data.assign(static_cast<size_t>(w) * h, 0);
  return g;
}

void H(BinaryGrid& g, int row, int c0, int c1) {
  for (int c = c0; c <= c1; ++c) g.SetValue(c, row, 1);
}
void V(BinaryGrid& g, int col, int r0, int r1) {
  for (int r = r0; r <= r1; ++r) g.SetValue(col, r, 1);
}

AnchorStation A(const std::string& id, double x, double y) {
  AnchorStation a;
  a.id = id;
  a.x = x;
  a.y = y;
  return a;
}

void Dump(const char* name, const TopologyBuildResult& r) {
  std::printf("[%s] success=%d err=\"%s\"\n", name, r.success ? 1 : 0,
              r.error_message.c_str());
  if (!r.success) return;
  std::printf("  stations=%zu road_nodes=%zu edges=%zu\n",
              r.catalog.stations.size(), r.catalog.road_nodes.size(),
              r.catalog.edges.size());
  for (const auto& e : r.catalog.edges) {
    std::printf("  edge %s -> %s dist=%.3f pts=%zu", e.from.c_str(),
                e.to.c_str(), e.distance_m, e.polyline.size());
    bool self = (e.from == e.to);
    std::printf("%s\n", self ? "  <== SELF LOOP" : "");
  }
}

}  // namespace

int main() {
  // ---- P1: pure closed ring (5x5 perimeter), 1 anchor on ring ----
  {
    auto info = MakeMapInfo(12, 12, 0.05);
    auto sk = MakeSkeleton(12, 12);
    // perimeter of cols 2..6, rows 2..6
    H(sk, 2, 2, 6);
    H(sk, 6, 2, 6);
    V(sk, 2, 2, 6);
    V(sk, 6, 2, 6);
    TopologyBuilderConfig cfg;
    cfg.max_snap_dist_m = 2.0;
    auto r = BuildTopologyCatalog(sk, info, {A("s1", 0.125, 0.125)}, cfg);
    Dump("P1 ring 1 anchor", r);
    if (r.success && r.catalog.stations.size() == 1) {
      auto path = catalog::FindRoutePath(r.catalog, "s1", "s1");
      std::printf("  FindRoutePath(s1,s1) has=%d\n", path.has_value() ? 1 : 0);
    }
  }

  // ---- P2: pure ring, 0 anchors ----
  {
    auto info = MakeMapInfo(12, 12, 0.05);
    auto sk = MakeSkeleton(12, 12);
    H(sk, 2, 2, 6);
    H(sk, 6, 2, 6);
    V(sk, 2, 2, 6);
    V(sk, 6, 2, 6);
    TopologyBuilderConfig cfg;
    auto r = BuildTopologyCatalog(sk, info, {}, cfg);
    Dump("P2 ring 0 anchors", r);
  }

  // ---- P3: P-shape (stem + ring at junction), 1 anchor at stem end ----
  {
    auto info = MakeMapInfo(14, 12, 0.05);
    auto sk = MakeSkeleton(14, 12);
    H(sk, 2, 4, 8);
    H(sk, 6, 4, 8);
    V(sk, 4, 2, 6);
    V(sk, 8, 2, 6);
    H(sk, 4, 0, 3);  // stem attached to ring left side at (4,4)
    TopologyBuilderConfig cfg;
    cfg.max_snap_dist_m = 2.0;
    auto r = BuildTopologyCatalog(sk, info, {A("s1", 0.025, 0.225)}, cfg);
    Dump("P3 P-shape", r);
  }

  // ---- P4: two anchors on the SAME edge at different positions ----
  {
    auto info = MakeMapInfo(40, 11, 0.05);
    auto sk = MakeSkeleton(40, 11);
    H(sk, 5, 0, 39);
    TopologyBuilderConfig cfg;
    cfg.max_snap_dist_m = 2.0;
    std::vector<AnchorStation> anchors{A("left", 0.025, 0.275),
                                       A("mid", 1.0, 0.275),
                                       A("right", 1.975, 0.275)};
    auto r = BuildTopologyCatalog(sk, info, anchors, cfg);
    Dump("P4 three anchors one edge", r);
    if (r.success) {
      for (size_t i = 0; i < r.catalog.stations.size(); ++i) {
        for (size_t j = i + 1; j < r.catalog.stations.size(); ++j) {
          auto p = catalog::FindRoutePath(
              r.catalog, r.catalog.stations[i].id, r.catalog.stations[j].id);
          std::printf("  path %s<->%s has=%d\n",
                      r.catalog.stations[i].id.c_str(),
                      r.catalog.stations[j].id.c_str(), p.has_value() ? 1 : 0);
        }
      }
    }
  }

  // ---- P5: two coincident anchors at same point ----
  {
    auto info = MakeMapInfo(40, 11, 0.05);
    auto sk = MakeSkeleton(40, 11);
    H(sk, 5, 0, 39);
    TopologyBuilderConfig cfg;
    cfg.max_snap_dist_m = 2.0;
    std::vector<AnchorStation> anchors{A("a1", 1.0, 0.275),
                                       A("a2", 1.0, 0.275)};
    auto r = BuildTopologyCatalog(sk, info, anchors, cfg);
    Dump("P5 coincident anchors", r);
  }

  // ---- P6: single anchor only ----
  {
    auto info = MakeMapInfo(40, 11, 0.05);
    auto sk = MakeSkeleton(40, 11);
    H(sk, 5, 0, 39);
    TopologyBuilderConfig cfg;
    auto r = BuildTopologyCatalog(sk, info, {A("only", 1.0, 0.275)}, cfg);
    Dump("P6 single anchor", r);
  }

  // ---- P7: empty pixel skeleton (grid allocated, no skeleton pixels) ----
  {
    auto info = MakeMapInfo(10, 10, 0.05);
    auto sk = MakeSkeleton(10, 10);
    TopologyBuilderConfig cfg;
    auto r = BuildTopologyCatalog(sk, info, {A("s", 0.1, 0.1)}, cfg);
    Dump("P7 no skeleton pixels", r);
  }

  // ---- P8: 0x0 skeleton ----
  {
    auto info = MakeMapInfo(10, 10, 0.05);
    BinaryGrid sk;
    TopologyBuilderConfig cfg;
    auto r = BuildTopologyCatalog(sk, info, {A("s", 0.1, 0.1)}, cfg);
    Dump("P8 zero-size skeleton", r);
  }

  // ---- P9: anchor id colliding with generated road node id ----
  {
    auto info = MakeMapInfo(20, 11, 0.05);
    auto sk = MakeSkeleton(20, 11);
    H(sk, 5, 0, 19);
    TopologyBuilderConfig cfg;
    cfg.max_snap_dist_m = 2.0;
    auto r = BuildTopologyCatalog(sk, info, {A("rn_0_5", 0.025, 0.275)}, cfg);
    Dump("P9 id collision anchor==roadnode", r);
  }

  return 0;
}

