#include "amr_dispatcher_core/planning/topology_graph_builder.hpp"
#include <cstdio>
using namespace amr_dispatcher_core::planning;
int main() {
  MapGrid info; info.width=14; info.height=12; info.resolution=0.05;
  info.data.assign(14u*12u, kCellFree);
  BinaryGrid sk; sk.width=14; sk.height=12; sk.data.assign(14u*12u, 0);
  auto H=[&](int r,int c0,int c1){for(int c=c0;c<=c1;++c)sk.SetValue(c,r,1);};
  auto V=[&](int c,int r0,int r1){for(int r=r0;r<=r1;++r)sk.SetValue(c,r,1);};
  // Q: ring cols4..8 rows2..6 + stem from (6,6) down to (6,9)
  H(2,4,8); H(6,4,8); V(4,2,6); V(8,2,6); V(6,6,9);
  TopologyBuilderConfig cfg; cfg.max_snap_dist_m=2.0;
  // anchor on the ring top (6,2) center world: ((6+0.5)*.05,(2+0.5)*.05)=(0.325,0.125)
  // anchor on stem end (6,9) center: (0.325, 0.475)
  AnchorStation a1; a1.id="on_ring"; a1.x=0.325; a1.y=0.125;
  AnchorStation a2; a2.id="on_stem"; a2.x=0.325; a2.y=0.475;
  auto r = BuildTopologyCatalog(sk, info, {a1, a2}, cfg);
  std::printf("Q-shape success=%d err=%s\n", r.success?1:0, r.error_message.c_str());
  std::printf("  stations=%zu nodes=%zu edges=%zu\n", r.catalog.stations.size(),
              r.catalog.road_nodes.size(), r.catalog.edges.size());
  for (auto& e : r.catalog.edges)
    std::printf("  edge %s->%s dist=%.3f pts=%zu%s\n", e.from.c_str(), e.to.c_str(),
                e.distance_m, e.polyline.size(), e.from==e.to?" SELFLOOP":"");
  for (auto& n : r.catalog.road_nodes) std::printf("  node %s (%.3f,%.3f)\n", n.id.c_str(), n.x, n.y);
  return 0;
}
